    hame_refresh_plan_cancellation_info = PGFunction(
        schema="hame",
        signature="refresh_plan_cancellation_info(repealing_plan_id uuid)",
        definition="RETURNS void\n    LANGUAGE plpgsql\nAS $$\nDECLARE\n    cancellation record;\nBEGIN\n    -- hame.repealed_plans returns nothing when the plan matter is not\n    -- repealing, so this also clears the rows when the flag is unset.\n    DELETE FROM hame.plan_cancellation_info i\n    WHERE i.plan_id = $1\n        AND i.cancelled_plan_id NOT IN (\n            SELECT cancelled_plan_id FROM hame.repealed_plans($1)\n        );\n\n    INSERT INTO hame.plan_cancellation_info (\n        plan_id, cancelled_plan_id, cancels_entire_plan\n    )\n    SELECT $1, r.cancelled_plan_id, r.cancels_entire_plan\n    FROM hame.repealed_plans($1) r\n    ON CONFLICT (plan_id, cancelled_plan_id) DO UPDATE\n        SET cancels_entire_plan = excluded.cancels_entire_plan;\n\n    FOR cancellation IN\n        SELECT id, cancelled_plan_id, cancels_entire_plan\n        FROM hame.plan_cancellation_info\n        WHERE plan_id = $1\n    LOOP\n        DELETE FROM hame.plan_object_cancellation_info\n        WHERE plan_cancellation_info_id = cancellation.id;\n\n        -- Ryhti allows no plan object cancellation infos when the whole\n        -- plan is repealed.\n        CONTINUE WHEN cancellation.cancels_entire_plan;\n\n        -- hame.repealed_plan_objects returns the columns below in this\n        -- order.\n        INSERT INTO hame.plan_object_cancellation_info (\n            plan_cancellation_info_id,\n            land_use_area_id,\n            other_area_id,\n            line_id,\n            point_id,\n            cancels_entire_plan_object,\n            remaining_valid_geom_polygon,\n            remaining_valid_geom_line,\n            remaining_valid_geom_point\n        )\n        SELECT cancellation.id, o.*\n        FROM hame.repealed_plan_objects(\n            $1, cancellation.cancelled_plan_id\n        ) o;\n    END LOOP;\nEND;\n$$",
    )
    op.drop_entity(hame_refresh_plan_cancellation_info)

    hame_plan_matter_valid = PGView(
        schema="hame",
        signature="plan_matter_valid",
        definition="WITH RECURSIVE plan_type_root AS (\n         SELECT plan_type.id,\n            plan_type.id AS root_id\n           FROM codes.plan_type\n          WHERE (plan_type.level = 1)\n        UNION ALL\n         SELECT child.id,\n            r.root_id\n           FROM (plan_type_root r\n             JOIN codes.plan_type child ON ((child.parent_id = r.id)))\n        )\n SELECT m.name,\n    m.description,\n    m.permanent_plan_identifier,\n    m.producers_plan_identifier,\n    m.case_identifier,\n    m.record_number,\n    m.digital_origin_id,\n    m.plan_type_id,\n    m.organisation_id,\n    m.id,\n    m.creator,\n    m.created_at,\n    m.modified_at,\n    m.modifier,\n    root.value AS plan_type\n   FROM ((hame.plan_matter m\n     LEFT JOIN plan_type_root ptr ON ((ptr.id = m.plan_type_id)))\n     LEFT JOIN codes.plan_type root ON ((root.id = ptr.root_id)))\n  WHERE (EXISTS ( SELECT 1\n           FROM hame.plan_valid p\n          WHERE (p.plan_matter_id = m.id)))",
    )
    op.create_entity(hame_plan_matter_valid)
    grant_select()

    op.drop_column("plan_matter", "repealing", schema="hame")

    # ### end Alembic commands ###
